def bubble_sort(arr):
    """Sort an array in ascending order using Bubble Sort."""
    a = arr.copy()
    for i in range(len(a)):
        swapped = False
        for j in range(len(a) - 1 - i):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                swapped = True
        if not swapped:
            break
    return a

bubble_sort.java:
public static int[] bubbleSort(int[] arr) {
    int[] a = arr.clone();
    for (int i = 0; i < a.length; i++) {
        boolean swapped = false;
        for (int j = 0; j < a.length - 1 - i; j++) {
            if (a[j] > a[j + 1]) {
                int temp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = temp;
                swapped = true;
            }
        }
        if (!swapped) break;
    }
    return a;
}

