def P006(arr):
    """Return sorted array and total shift count."""
    a = arr.copy()
    shift_count = 0
    for i in range(1, len(a)):
        key = a[i]
        j = i - 1
        while j >= 0 and a[j] > key:
            a[j + 1] = a[j]
            j -= 1
            shift_count += 1
        a[j + 1] = key
    return {"sorted_array": a, "shift_count": shift_count}

